import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'
import * as THREE from 'three'
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js'
import { animationKindsOf, extractSceneGraph } from '../lib/sceneGraph.js'
import { config } from '../config.js'
import { planAnimationFrames } from '../puppeteerRenderer.js'

/**
 * The loader-side contract of the committed glTF fixtures (generated by
 * test/fixtures/animated/generate.mjs): what three actually hands the viewer,
 * the worker's thumbnail render and the scene-graph extractor for a skinned
 * clip, a morph clip, vertex colours, embedded textures and the combination.
 *
 * GLTFLoader expects a browser: three's FileLoader wants `self`, its progress
 * stream emits `ProgressEvent`, and embedded PNGs decode through
 * `createImageBitmap`. None of them render here - the shims let the data-URI
 * images resolve so the tests can assert the loader wired the texture slots.
 */
globalThis.self = globalThis
globalThis.ProgressEvent = class ProgressEvent {
  constructor(type, init = {}) {
    this.type = type
    Object.assign(this, init)
  }
}
globalThis.createImageBitmap = async () => ({
  width: 4,
  height: 4,
  close() {},
})

function loadFixture(name) {
  const source = readFileSync(
    new URL(`./fixtures/animated/${name}.gltf`, import.meta.url),
    'utf8'
  )
  return new Promise((resolve, reject) => {
    new GLTFLoader().parse(
      source,
      '',
      gltf => {
        // GLTFLoader keeps clips on the parse result; the render page copies
        // them onto the scene (render-template.html loadModel) because every
        // consumer walks the model root.
        gltf.scene.animations = gltf.animations
        resolve(gltf)
      },
      reject
    )
  })
}

function firstMesh(root) {
  let found = null
  root.traverse(object => {
    if (!found && object.isMesh) {
      found = object
    }
  })
  return found
}

function shapeKeysByMesh(graph) {
  return graph.parts
    .filter(part => Array.isArray(part.shapeKeys) && part.shapeKeys.length > 0)
    .map(part => ({ meshName: part.name, shapeKeys: part.shapeKeys }))
}

describe('animated glTF fixtures', () => {
  it('skinned-clip: one skeletal clip over a two-joint skeleton', async () => {
    const gltf = await loadFixture('skinned-clip')

    expect(gltf.animations.map(clip => clip.name)).toEqual(['Wave'])
    expect(gltf.animations[0].duration).toBeCloseTo(1)

    const mesh = firstMesh(gltf.scene)
    expect(mesh.isSkinnedMesh).toBe(true)
    expect(mesh.skeleton.bones).toHaveLength(2)
    expect(mesh.morphTargetInfluences).toBeUndefined()
  })

  it('morph-clip: two named morph targets driven by a weights clip', async () => {
    const gltf = await loadFixture('morph-clip')

    expect(gltf.animations.map(clip => clip.name)).toEqual(['Pulse'])
    expect(gltf.animations[0].duration).toBeCloseTo(2)

    const mesh = firstMesh(gltf.scene)
    expect(mesh.morphTargetDictionary).toEqual({ Squash: 0, Stretch: 1 })
    expect(mesh.morphTargetInfluences).toEqual([0, 0])
    expect(gltf.animations[0].tracks[0].name).toBe('Box.morphTargetInfluences')
  })

  it('vertex-colors: one COLOR_0 per vertex, no clips', async () => {
    const gltf = await loadFixture('vertex-colors')

    expect(gltf.animations).toHaveLength(0)

    const mesh = firstMesh(gltf.scene)
    expect(mesh.geometry.attributes.color).toBeTruthy()
    expect(mesh.geometry.attributes.color.count).toBe(8)
    expect(mesh.material.vertexColors).toBe(true)
  })

  it('textured: embedded base colour and normal textures resolve', async () => {
    const gltf = await loadFixture('textured')

    expect(gltf.animations).toHaveLength(0)

    const mesh = firstMesh(gltf.scene)
    expect(mesh.geometry.attributes.uv).toBeTruthy()
    expect(mesh.material.map).toBeTruthy()
    expect(mesh.material.normalMap).toBeTruthy()
    expect(mesh.material.map.image).toBeTruthy()
    expect(mesh.material.normalMap.image).toBeTruthy()
  })

  it('combined: skin, morphs, COLOR_0, textures and both clips together', async () => {
    const gltf = await loadFixture('combined')

    expect(gltf.animations.map(clip => clip.name)).toEqual(['Wave', 'Pulse'])
    expect(gltf.animations.map(clip => clip.duration)).toEqual([1, 2])

    const mesh = firstMesh(gltf.scene)
    expect(mesh.isSkinnedMesh).toBe(true)
    expect(mesh.skeleton.bones).toHaveLength(2)
    expect(mesh.morphTargetDictionary).toEqual({ Squash: 0, Stretch: 1 })
    expect(mesh.geometry.attributes.color).toBeTruthy()
    expect(mesh.material.map).toBeTruthy()
    expect(mesh.material.normalMap).toBeTruthy()
  })
})

describe('animation kinds from the shared scene-graph extractor', () => {
  it('skinned-clip: Wave is skeletal with its duration', async () => {
    const graph = extractSceneGraph(
      (await loadFixture('skinned-clip')).scene,
      THREE,
      { sourceFormat: 'gltf' }
    )

    expect(graph.rollups.animations).toEqual([
      { name: 'Wave', durationSeconds: 1, kinds: ['skeletal'] },
    ])
  })

  it('morph-clip: Pulse is morph and the shape keys name their mesh', async () => {
    const graph = extractSceneGraph(
      (await loadFixture('morph-clip')).scene,
      THREE,
      { sourceFormat: 'gltf' }
    )

    expect(graph.rollups.animations).toEqual([
      { name: 'Pulse', durationSeconds: 2, kinds: ['morph'] },
    ])
    expect(shapeKeysByMesh(graph)).toEqual([
      { meshName: 'Box', shapeKeys: ['Squash', 'Stretch'] },
    ])
  })

  it('combined: Wave skeletal, Pulse morph, shape keys Squash/Stretch', async () => {
    const graph = extractSceneGraph(
      (await loadFixture('combined')).scene,
      THREE,
      { sourceFormat: 'gltf' }
    )

    expect(graph.rollups.animations).toEqual([
      { name: 'Wave', durationSeconds: 1, kinds: ['skeletal'] },
      { name: 'Pulse', durationSeconds: 2, kinds: ['morph'] },
    ])
    expect(shapeKeysByMesh(graph)).toEqual([
      { meshName: 'Box', shapeKeys: ['Squash', 'Stretch'] },
    ])
  })

  it('classifies material tracks and reports mixed kinds canonically', () => {
    const clip = new THREE.AnimationClip('Fx', 1, [
      new THREE.QuaternionKeyframeTrack(
        'Bone.quaternion',
        [0, 1],
        [0, 0, 0, 1, 0, 0, 0, 1]
      ),
      new THREE.NumberKeyframeTrack(
        'Box.morphTargetInfluences',
        [0, 1],
        [0, 1]
      ),
      new THREE.ColorKeyframeTrack('Mat.color', [0, 1], [1, 0, 0, 0, 1, 0]),
    ])

    expect(animationKindsOf(clip)).toEqual(['skeletal', 'morph', 'material'])
  })
})

describe('animation thumbnail path from the committed fixtures', () => {
  const limits = config.animationClip

  it('skinned-clip: animated path, 15 frames at ~66.7 ms', async () => {
    const gltf = await loadFixture('skinned-clip')

    expect(gltf.scene.animations.length).toBeGreaterThanOrEqual(1)

    const plan = planAnimationFrames(gltf.scene.animations[0].duration, limits)
    expect(plan.frameCount).toBe(15)
    expect(plan.frameDelayMs).toBeCloseTo(66.7, 1)
  })

  it('morph-clip: animated path, 30 frames at ~66.7 ms', async () => {
    const gltf = await loadFixture('morph-clip')

    expect(gltf.scene.animations.length).toBeGreaterThanOrEqual(1)

    const plan = planAnimationFrames(gltf.scene.animations[0].duration, limits)
    expect(plan.frameCount).toBe(30)
    expect(plan.frameDelayMs).toBeCloseTo(66.7, 1)
  })

  it('vertex-colors: no clips, the orbit path is used unchanged', async () => {
    const gltf = await loadFixture('vertex-colors')

    expect(gltf.scene.animations).toHaveLength(0)
  })
})
